// SupportFileAdministrationService 提供后台 File 治理能力。
type SupportFileAdministrationServiceServer interface {
	// 查询 File 详情。
	GetFile(context.Context, *AdminGetFileRequest) (*v1.File, error)
	// 查询 File 列表。
	ListFiles(context.Context, *AdminListFilesRequest) (*v1.ListFilesResponse, error)
	// 查询 Upload Session 列表。
	ListUploadSessions(context.Context, *AdminListUploadSessionsRequest) (*v1.ListUploadSessionsResponse, error)
	// 独立发布 App 公共资源。
	PublishStandaloneFile(context.Context, *AdminPublishStandaloneFileRequest) (*v1.File, error)
	// 永久阻断 File 公共访问。
	RevokeFile(context.Context, *AdminRevokeFileRequest) (*v1.File, error)
	// 查询 File Reference。
	ListFileReferences(context.Context, *AdminListFileReferencesRequest) (*v1.ListFileReferencesResponse, error)
	// 查询 File Event。
	ListFileEvents(context.Context, *AdminListFileEventsRequest) (*v1.ListFileEventsResponse, error)
	// 查询历史 File Review Attempt。
	ListFileReviewAttempts(context.Context, *AdminListFileReviewAttemptsRequest) (*v1.ListFileReviewAttemptsResponse, error)
	// 创建不可变 Policy Draft Revision。
	CreateFilePolicyDraft(context.Context, *AdminCreateFilePolicyDraftRequest) (*v1.FilePolicyRevision, error)
	// 对 Policy Draft Revision 执行结构化预检。
	PreflightFilePolicyDraft(context.Context, *AdminPreflightFilePolicyDraftRequest) (*v1.FilePolicyPreflight, error)
	// 激活已通过预检的 Policy Draft Revision。
	ActivateFilePolicyDraft(context.Context, *AdminActivateFilePolicyDraftRequest) (*v1.FilePolicyRevision, error)
	// 丢弃未使用的 Policy Draft Revision。
	DiscardFilePolicyDraft(context.Context, *AdminDiscardFilePolicyDraftRequest) (*emptypb.Empty, error)
	// 查询不可变 Policy Revision 历史。
	ListFilePolicyRevisions(context.Context, *AdminListFilePolicyRevisionsRequest) (*v1.ListFilePolicyRevisionsResponse, error)
	// 创建不可变 Provider Draft Revision。
	CreateStorageProviderDraft(context.Context, *AdminCreateStorageProviderDraftRequest) (*v1.StorageProviderRevision, error)
	// 对 Provider Draft 执行真实能力预检。
	PreflightStorageProviderDraft(context.Context, *AdminPreflightStorageProviderDraftRequest) (*v1.StorageProviderPreflight, error)
	// 激活已通过预检的 Provider Draft。
	ActivateStorageProviderDraft(context.Context, *AdminActivateStorageProviderDraftRequest) (*v1.StorageProviderRevision, error)
	// 丢弃未使用的 Provider Draft。
	DiscardStorageProviderDraft(context.Context, *AdminDiscardStorageProviderDraftRequest) (*emptypb.Empty, error)
	// 查询不可变 Provider Revision 历史。
	ListStorageProviderRevisions(context.Context, *AdminListStorageProviderRevisionsRequest) (*v1.ListStorageProviderRevisionsResponse, error)
	// 创建存储对账批次。
	CreateReconciliationBatch(context.Context, *AdminCreateReconciliationBatchRequest) (*v1.ReconciliationBatch, error)
	// 查询存储对账批次。
	ListReconciliationBatches(context.Context, *AdminListReconciliationBatchesRequest) (*v1.ListReconciliationBatchesResponse, error)
	// 查询存储对账明细。
	ListReconciliationItems(context.Context, *AdminListReconciliationItemsRequest) (*v1.ListReconciliationItemsResponse, error)
	// 查询异步治理任务。
	ListFileTasks(context.Context, *AdminListFileTasksRequest) (*v1.ListFileTasksResponse, error)
	// 重试失败任务。
	RetryFileTask(context.Context, *AdminRetryFileTaskRequest) (*v1.FileTask, error)
	mustEmbedUnimplementedSupportFileAdministrationServiceServer()
}

